// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint64 futureTime, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        uint64 now0 = uint64(block.timestamp);
        uint64 t = uint64(bound(uint256(futureTime), uint256(now0) + 1, uint256(now0) + 3650 days));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= t, "unlockTime must honor requested future unlock time");
    }
}
